d = LogNormalDistribution[0, 0.5];
{Mean[d], Median[d], Mode[d]}
EstimatedDistribution[data, LogNormalDistribution[m, s]]

d = ParetoDistribution[1, 1.5];
Mean[d]
Variance[d] (* Infinity for alpha <= 2 *)

cost = TriangularDistribution[{80, 150}, 100];
NExpectation[x, x \[Distributed] cost]
RandomVariate[cost, 10^4] // Mean

d = MultinormalDistribution[{0, 0}, {{1, 0.8}, {0.8, 1}}];
pts = RandomVariate[d, 500];
ListPlot[pts]
MarginalDistribution[d, 1]

mix = MixtureDistribution[{0.3, 0.7}, {NormalDistribution[0, 1], NormalDistribution[4, 0.5]}];
Plot[PDF[mix, x], {x, -3, 7}]
EstimatedDistribution[data, MixtureDistribution[{w, 1 - w}, {NormalDistribution[a, s], NormalDistribution[b, t]}]]

d = TruncatedDistribution[{0, Infinity}, NormalDistribution[1, 1]];
Mean[d]
RandomVariate[d, 5]

joint = ProductDistribution[NormalDistribution[], ExponentialDistribution[1]];
RandomVariate[joint, 3]
Probability[x < y, {x, y} \[Distributed] joint]

sys = ReliabilityDistribution[x && (y || z), {{x, ExponentialDistribution[1/1000]}, {y, WeibullDistribution[2, 800]}, {z, WeibullDistribution[2, 800]}}];
Mean[sys]
Plot[SurvivalFunction[sys, t], {t, 0, 3000}]
